import{_ as e,a,o,a6 as i}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Attribute Family — Update","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-family-update","title":"Update Attribute Family","description":"Update a family. Inside `attribute_groups`, items keyed by numeric id update existing groups; items keyed by `group_*` create new groups; omitted existing ids are deleted.","query":"curl -X PUT \\"https://your-domain.com/api/admin/catalog/families/4\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"code\\": \\"electronics\\",\\n    \\"name\\": \\"Electronics (updated)\\",\\n    \\"attribute_groups\\": {\\n      \\"11\\": {\\n        \\"code\\": \\"general\\",\\n        \\"name\\": \\"General\\",\\n        \\"column\\": 1,\\n        \\"position\\": 1,\\n        \\"custom_attributes\\": [ { \\"id\\": 1, \\"position\\": 1 } ]\\n      },\\n      \\"group_new_1\\": {\\n        \\"code\\": \\"pricing\\",\\n        \\"name\\": \\"Pricing\\",\\n        \\"column\\": 2,\\n        \\"position\\": 2,\\n        \\"custom_attributes\\": [ { \\"id\\": 11, \\"position\\": 1 } ]\\n      }\\n    }\\n  }\'\\n","variables":"id=4\\n","response":"{\\n  \\"id\\": 4,\\n  \\"code\\": \\"electronics\\",\\n  \\"name\\": \\"Electronics (updated)\\"\\n}\\n","commonErrors":[{"error":"Validation (422)","cause":"`code` duplicate or other body validation issue","solution":"Verify that the supplied code is unique and well-formed"},{"error":"Not Found (404)","cause":"Unknown family id","solution":"Verify the id with the listing endpoint"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/families/families-update.md","filePath":"api/rest-api/admin/catalog/families/families-update.md","lastUpdated":1787290888000}'),d={name:"api/rest-api/admin/catalog/families/families-update.md"};function r(n,t,s,c,l,p){return o(),a("div",null,t[0]||(t[0]=[i('<h1 id="attribute-family-—-update" tabindex="-1">Attribute Family — Update <a class="header-anchor" href="#attribute-family-—-update" aria-label="Permalink to &quot;Attribute Family — Update&quot;">​</a></h1><p>Updates an existing attribute family. Mirrors <strong>Catalog → Attribute Families → Edit</strong> in the Bagisto admin panel — same partial-update semantics for nested attribute groups.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/families/{id}</code></td><td>PUT</td></tr></tbody></table><p><code>{id}</code> must be a positive integer.</p><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><p>Top-level fields are <code>code</code> (required), <code>name</code> (required), and <code>attribute_groups</code> (object, optional).</p><h3 id="attribute-groups-semantics" tabindex="-1"><code>attribute_groups</code> semantics <a class="header-anchor" href="#attribute-groups-semantics" aria-label="Permalink to &quot;`attribute_groups` semantics&quot;">​</a></h3><p>The <code>attribute_groups</code> field is an <strong>object</strong> keyed by either a numeric existing group id or a <code>group_*</code> placeholder for a new group:</p><table tabindex="0"><thead><tr><th>Key shape</th><th>Effect</th></tr></thead><tbody><tr><td><code>&quot;11&quot;</code> (numeric id)</td><td>Updates the existing group with id 11</td></tr><tr><td><code>&quot;group_new_1&quot;</code></td><td>Creates a new group</td></tr><tr><td>existing id <strong>omitted</strong> from the payload</td><td>Deletes that group</td></tr></tbody></table><p>Each value is a group object:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>code</code> / <code>name</code> / <code>column</code> / <code>position</code></td><td>scalars</td><td>Same fields as on Create</td></tr><tr><td><code>custom_attributes</code></td><td>array</td><td><code>[{ id, position }, ...]</code> — full replacement set for the group</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code>. Same shape as <a href="/api/rest-api/admin/catalog/families/families-detail.html"><code>GET /api/admin/catalog/families/{id}</code></a>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid Bearer token</td></tr><tr><td><code>404 Not Found</code></td><td>The family does not exist</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td><code>code</code> duplicate or other body validation issue</td></tr></tbody></table>',16)]))}const h=e(d,[["render",r]]);export{m as __pageData,h as default};
